static uint32_t prod(uint32_t xy, uint32_t wh, volatile uint32_t **gp0, volatile uint32_t **gp1) {
    uint32_t st;
    __asm__ volatile(
        ".set noreorder\n"
        "lui $t1, 0x0100\n"
        "lui $t2, 0xc000\n"
        "lw $t3, 0(%3)\n"
        "nop\n"
        "sw $t1, 0($t3)\n"
        "lw $t3, 0(%3)\n"
        "nop\n"
        "sw $t2, 0($t3)\n"
        "lw $t3, 0(%3)\n"
        "nop\n"
        "sw %1, 0($t3)\n"
        "lw $t3, 0(%3)\n"
        "nop\n"
        "sw %2, 0($t3)\n"
        "lw $t3, 0(%4)\n"
        "nop\n"
        "lw %0, 0($t3)\n"
        "nop\n"
        ".set reorder\n"
        : "=r"(st) : "r"(xy), "r"(wh), "r"(gp0), "r"(gp1) : "t1", "t2", "t3", "memory");
    return st;
}

